/// One glyph: the path, its box, and how it fills.
struct SVGGlyph {
    let d: String
    let box: CGSize
    let evenOdd: Bool
}

/// A glyph, in a colour, scaled to fit.
struct NexusGlyphView: View {
    let glyph: NexusGlyph
    var color: Color = .primary
    init(_ glyph: NexusGlyph, color: Color = .primary) { self.glyph = glyph; self.color = color }
    var body: some View {
        let g = glyph.glyph
        SVGPathShape(d: g.d, box: g.box)
            .fill(color, style: FillStyle(eoFill: g.evenOdd))
            .aspectRatio(g.box.width / g.box.height, contentMode: .fit)
    }
}
